import{HostDocument}from'./host-document';import{HostEditorRuntime}from'./editor-runtime';import{DEFAULT_WHITESPACE}from'../../../../src/shared/settings/design-whitespace';import{planWhitespace}from'../../../../src/renderer/src/design-patent/correction/klecks-whitespace';
const check=(v:unknown,m:string)=>{if(!v)throw Error(m);};
export async function verifyWhitespace(){
 const edge=document.createElement('canvas');edge.width=edge.height=4;const ec=edge.getContext('2d')!;ec.fillStyle='white';ec.fillRect(0,0,4,4);ec.fillStyle='black';ec.fillRect(1,1,2,2);
 const layer={name:'Original',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over' as const,image:edge};
 const background=new HostDocument({projectId:'whitespace-background',width:4,height:4,layers:[layer]},true);
 const pad=planWhitespace(4,4,null,{...DEFAULT_WHITESPACE,trim:false,pad:true,top:1,right:1,bottom:1,left:1});
 try{
  const id=background.canvas.getLayer(0).id;background.setLayerLocks(id,{all:true,pixels:true,position:true,alpha:true});const locks=JSON.stringify(background.getLayerLocks(id));
  await background.adjustWhitespace(pad,'white');check(background.canvas.getLayerCount()===1&&background.getDisplayComposite().getContext('2d')!.getImageData(0,0,1,1).data[3]===255,'Opaque background padding wrong');background.undo();
  await background.adjustWhitespace(pad,'transparent');check(!background.history.getComposed().layerMap[id].hostBackground&&JSON.stringify(background.getLayerLocks(id))===locks,'Transparent padding lost locks or failed background conversion');check(background.getDisplayComposite().getContext('2d')!.getImageData(0,0,1,1).data[3]===0,'Background margin not transparent');
 }finally{background.destroy();}
 const hidden=new HostDocument({projectId:'whitespace-hidden',width:4,height:4,layers:[layer,{...layer,name:'Hidden',isVisible:false}]});
 try{await hidden.adjustWhitespace(pad,'white');check(hidden.canvas.getLayerCount()===3&&!hidden.canvas.getLayer(1).isVisible,'Hidden layer lost or exposed');check(hidden.canvas.getLayer(1).context.getImageData(2,2,1,1).data[0]===0,'Hidden layer not translated');hidden.undo();const trim=planWhitespace(4,4,{left:1,top:1,width:2,height:2},DEFAULT_WHITESPACE);await hidden.adjustWhitespace(trim,'transparent');await hidden.adjustWhitespace(planWhitespace(2,2,null,{...DEFAULT_WHITESPACE,trim:false,pad:true,top:1,right:1,bottom:1,left:1}),'transparent');check(hidden.canvas.getLayer(0).context.getImageData(0,0,1,1).data[3]===0,'Padding resurrected cropped pixels');}finally{hidden.destroy();}
 const full=new HostDocument({projectId:'whitespace-cap',width:4,height:4,layers:Array.from({length:16},()=>({...layer}))});
 try{let rejected=false;try{await full.adjustWhitespace(pad,'white');}catch(e){rejected=e instanceof Error&&e.message.includes('16');}check(rejected&&full.canvas.getWidth()===4&&full.canvas.getLayerCount()===16,'Layer cap failed without safe rejection');await full.adjustWhitespace(pad,'transparent');check(full.canvas.getWidth()===6&&full.canvas.getLayerCount()===16,'Transparent padding at layer cap failed');}finally{full.destroy();edge.width=edge.height=0;}
 const source=document.createElement('canvas');source.width=10;source.height=8;const c=source.getContext('2d')!;c.fillStyle='white';c.fillRect(0,0,10,8);c.fillStyle='black';c.fillRect(2,3,5,3);
 const base=new HostDocument({projectId:'whitespace',width:10,height:8,layers:[{name:'Base',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image:source}]});
 const plan=planWhitespace(10,8,{left:2,top:3,width:5,height:3},{...DEFAULT_WHITESPACE,pad:true,top:1,right:2,bottom:3,left:4});
 try{
  base.select([[[[2,3],[7,3],[7,6],[2,6],[2,3]]]],'replace');const selection=JSON.stringify(base.history.getComposed().selection),history=base.capture().history.totalActions;
  await base.adjustWhitespace(plan,'white');check(base.canvas.getWidth()===11&&base.canvas.getHeight()===7,'Whitespace size wrong');check(base.canvas.getLayerCount()===2,'White margin layer missing');
  const p=base.getDisplayComposite().getContext('2d')!;check(p.getImageData(0,0,1,1).data[0]===255&&p.getImageData(4,1,1,1).data[0]===0,'White margin/subject moved incorrectly');check(base.selectionContains(4.5,1.5),'Selection did not translate');
  check(base.capture().history.totalActions===history+1,'Whitespace created multiple undo steps');base.undo();check(base.canvas.getWidth()===10&&base.canvas.getLayerCount()===1&&JSON.stringify(base.history.getComposed().selection)===selection,'Whitespace undo lost source or selection');base.redo();
  const project=await base.exportProject(),restored=await HostDocument.openProject(project);try{check(restored.canvas.getWidth()===11&&restored.getDisplayComposite().getContext('2d')!.getImageData(4,1,1,1).data[0]===0,'Whitespace save/reopen failed');}finally{restored.destroy();}
  base.undo();const controller=new AbortController(),count=base.capture().history.totalActions,pending=base.adjustWhitespace(plan,'transparent',controller.signal);controller.abort();try{await pending;}catch{}check(base.canvas.getWidth()===10&&base.capture().history.totalActions===count,'Cancelled whitespace changed original');
  const push=base.history.push.bind(base.history);base.history.push=()=>{throw Error('admission rejected');};try{await base.adjustWhitespace(plan,'white');}catch{}finally{base.history.push=push;}check(base.canvas.getWidth()===10&&base.canvas.getLayerCount()===1,'Failed whitespace changed original');
  await base.adjustWhitespace(plan,'transparent');check(base.canvas.getLayerCount()===1&&base.canvas.getLayer(0).context.getImageData(0,0,1,1).data[3]===0,'Transparent padding flattened image');
 }finally{base.destroy();source.width=source.height=0;}
 const image=document.createElement('canvas');image.width=1600;image.height=1200;const x=image.getContext('2d')!;x.fillStyle='white';x.fillRect(0,0,1600,1200);x.fillStyle='black';x.fillRect(100,200,800,600);
 const original=new HostDocument({projectId:'whitespace-runtime',width:1600,height:1200,layers:[{name:'Base',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image}]});const host=document.createElement('div');host.style.cssText='width:800px;height:600px';document.body.append(host);const errors:unknown[]=[];const r=new HostEditorRuntime(host,'windows',{changed(){},error:e=>errors.push(e)});
 const settle=async()=>{for(let i=0;i<4000&&r.state.whitespace?.busy;i++)await new Promise(z=>setTimeout(z,1));};
 try{r.sync(['a']);await r.openProject('a',()=>original.exportProject());const before=r.workspace.document!.contentIdentity();r.beginWhitespace('trim');await settle();check(r.state.whitespace?.plan?.rect.width===800&&r.state.whitespace.canApply,'Automatic trim preview failed');check(before===r.workspace.document!.contentIdentity(),'Preview mutated pixels');r.cancelWhitespace();check(!r.state.pending&&before===r.workspace.document!.contentIdentity(),'Trim cancel changed pixels');
 r.beginWhitespace('trim');await settle();r.applyWhitespace();r.cancelWhitespace();await settle();check(!r.state.pending&&!r.state.whitespace&&before===r.workspace.document!.contentIdentity(),'In-progress apply cancellation changed pixels or left editor blocked');
 r.beginWhitespace('trim');r.updateWhitespace({...r.state.whitespace!.options,pad:true,left:10,right:10,top:10,bottom:10});await settle();r.applyWhitespace();await settle();check(!r.state.pending&&!r.state.whitespace&&r.state.size?.width===820,'Trim and pad did not apply');r.dispatch({action:'undo'});check(r.state.size?.width===1600&&before===r.workspace.document!.contentIdentity(),'Runtime undo failed');check(!errors.length,'Runtime reported errors');}finally{r.destroy();original.destroy();image.width=image.height=0;host.remove();}
}
